package com.zomiggy.entity;
import jakarta.persistence.*;
@Entity public class Restaurant { @Id private Long id; @Column(nullable=false) private String name; private double rating; private String time; private String cuisine; private String imageUrl; private String offer; protected Restaurant(){} public Restaurant(long id,String name,double rating,String time,String cuisine,String imageUrl,String offer){this.id=id;this.name=name;this.rating=rating;this.time=time;this.cuisine=cuisine;this.imageUrl=imageUrl;this.offer=offer;} public Long getId(){return id;} public String getName(){return name;} public double getRating(){return rating;} public String getTime(){return time;} public String getCuisine(){return cuisine;} public String getImageUrl(){return imageUrl;} public String getOffer(){return offer;} }